/**
 * Synthetic service documents for the demo (generated by scripts/generate-service-docs.ts into
 * public/service-samples). Each sample carries its ground truth, so it doubles as the AI control set.
 * Workshops, insurers and numbers are fictional; the plates are those of the demo fleet.
 */

export type ServiceDocKind = "przeglad" | "oc" | "tachograf" | "serwis" | "atp";

export type ServiceTruth = {
  kind: ServiceDocKind;
  plates: string;
  /** ISO dates (yyyy-mm-dd), as printed on the document. */
  performedOn: string;
  validUntil: string | null;
  odometerKm: number | null;
  docNumber: string;
  issuer: string;
};

export type ServiceSample = { id: string; file: string; label: string; title: string; truth: ServiceTruth; lines: [string, string][] };

